// Puzzle shrines (WP7, DESIGN 13.2): 11 overworld shrines, five puzzle types parameterised by the world seed:
//   plates   - step on the plates in the order the flashing shows
//   braziers - light every brazier; lighting one toggles its neighbours (generated from the solved state, so solvable)
//   blocks   - push 3 blocks onto 3 marks (generated by reverse pulls from the solved state, so solvable; altar resets)
//   tidelock - reach the pedestal on its island across the flats at low tide
//   echo     - repeat a 4-7 note sequence by striking the chimes
// Reward (once per world): 100 * tier^2 Glint, 2 tide_token and a shrine-pool trinket the solver lacks (+relic_01 at
// the Greenmarrow shrine). Also owns the relic dig spots (DESIGN A.5): 10 digs with RMB empties a spot.
//
// Pieces are structures of kind `shrine_piece` (pub `it` = piece type, `on` = state, `lv` = note/index) so the client can
// target them with `use`; the altar is the natural structure `shrine`. Action: shrine.act {id, i}. Service: buildShrine.

import { PLOT } from '../../../shared/config.js';
import { T, FLAG, BIOME_TIER, plotIndex } from '../../../shared/grid.js';
import { isInt } from '../../../shared/protocol.js';
import { createRng, hashString, seededShuffle } from '../../../shared/rng.js';
import { placeNatural, reserve } from '../worldgen/features.js';

export const PUZZLES = Object.freeze(['plates', 'braziers', 'blocks', 'tidelock', 'echo']);
const SHOW_STEP = 0.8, SHOW_ON = 0.5, SHOW_PAUSE = 3, IDLE_RESET = 10;

const GAMES = new WeakMap();
const G = (game) => GAMES.get(game);

// Seeded puzzle type per shrine plot: the 11 shrine plots get a shuffled bag covering all five types.
export function shrineType(game, plot) {
  const shrines = game.world.plots.filter((p) => p.feature === 'shrine').map((p) => plotIndex(p.px, p.py)).sort((a, b) => a - b);
  const bag = [];
  while (bag.length < shrines.length) bag.push(...PUZZLES);
  const order = seededShuffle(bag.slice(0, shrines.length), (game.world.seed ^ hashString('shrine-types')) >>> 0);
  const i = shrines.indexOf(plotIndex(plot.px, plot.py));
  let type = order[i] ?? 'plates';
  if (plot.biome === 'greenmarrow' && (type === 'blocks' || type === 'tidelock')) type = 'plates';
  return type;
}

// ---------------------------------------------------------------- building

function piece(game, realm, shrine, i, type, tx, ty, { solid = false, on = 0, lv = 0 } = {}) {
  const e = placeNatural(game, realm, 'shrine_piece', tx, ty, { w: 1, h: 1, solid, shrine: shrine.id, i, it: type, on, lv }, { it: type, on, lv });
  e.radius = 0.5;
  shrine.data.pieces.push(e.id);
  return e;
}

function buildShrine(game, realm, plot, lx, ly, forceType = null) {
  const tier = BIOME_TIER[plot.biome] ?? 1;
  const type = PUZZLES.includes(forceType) ? forceType : shrineType(game, plot);
  const rng = createRng((game.world.seed ^ hashString(`shrine:${plot.px},${plot.py}`)) >>> 0);
  const ox = plot.px * PLOT, oy = plot.py * PLOT;
  reserve(realm, plot, lx - 5, ly - 5, 11, 11, 0);
  const shrine = placeNatural(game, realm, 'shrine', ox + lx - 1, oy + ly - 4, {
    puzzle: type, tier, solved: false, pieces: [], px: plot.px, py: plot.py, seq: [], prog: 0, show: 0, showT: 0, idle: 0,
  }, { it: type, p: 0 });
  const D = shrine.data;
  D.base = { x: ox + lx, y: oy + ly };
  const at = (dx, dy) => [ox + lx + dx, oy + ly + dy];
  if (type === 'plates') {
    const n = 4 + Math.floor(tier / 2);
    const spots = [];
    for (let row = 0; row < 2; row++) for (let c = -4; c <= 4; c += 2) spots.push([c + (row ? 1 : 0), row * 2 + 0]);
    const chosen = rng.shuffle(spots).slice(0, n).sort((a, b) => a[1] - b[1] || a[0] - b[0]);
    chosen.forEach(([dx, dy], i) => piece(game, realm, shrine, i, 'plate', ...at(dx, dy + 1)));
    const len = Math.min(n, 3 + Math.ceil(tier / 2));
    D.seq = rng.shuffle([...Array(n).keys()]).slice(0, len);
  } else if (type === 'braziers') {
    const cols = 3, rows = tier <= 2 ? 2 : 3;
    D.cols = cols; D.rows = rows;
    const n = cols * rows;
    D.lit = new Array(n).fill(1);
    const presses = rng.shuffle([...Array(n).keys()]).slice(0, rng.int(3, Math.min(5, n - 1)));
    for (const i of presses) toggleBraziers(D, i);
    if (D.lit.every(Boolean)) toggleBraziers(D, 0);
    for (let i = 0; i < n; i++) piece(game, realm, shrine, i, 'brazier', ...at((i % cols) * 2 - 2, Math.floor(i / cols) * 2), { solid: true, on: D.lit[i] });
  } else if (type === 'blocks') {
    const area = { x0: -4, y0: -1, x1: 4, y1: 4 };
    D.area = area;
    const marks = [];
    while (marks.length < 3) {
      const m = [rng.int(area.x0 + 1, area.x1 - 1), rng.int(area.y0 + 1, area.y1 - 1)];
      if (!marks.some((k) => Math.abs(k[0] - m[0]) + Math.abs(k[1] - m[1]) < 2)) marks.push(m);
    }
    const blocks = marks.map((m) => m.slice());
    const free = (x, y) => x >= area.x0 && x <= area.x1 && y >= area.y0 && y <= area.y1 && !blocks.some((b) => b[0] === x && b[1] === y);
    const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    D.pulls = [];
    for (let k = 0; k < 400 && (D.pulls.length < 18 || blocks.filter((b, i) => b[0] === marks[i][0] && b[1] === marks[i][1]).length > 0); k++) {
      const bi = rng.int(0, 2), [dx, dy] = rng.pick(dirs);
      const b = blocks[bi];
      if (free(b[0] + dx, b[1] + dy) && free(b[0] + 2 * dx, b[1] + 2 * dy)) { b[0] += dx; b[1] += dy; D.pulls.push([bi, dx, dy]); }
    }
    marks.forEach(([dx, dy], i) => piece(game, realm, shrine, i, 'mark', ...at(dx, dy)));
    D.start = blocks.map((b) => b.slice());
    blocks.forEach(([dx, dy], i) => piece(game, realm, shrine, 3 + i, 'block', ...at(dx, dy), { solid: true }));
    D.marks = marks;
  } else if (type === 'tidelock') {
    const [cx, cy] = at(0, 2);
    for (let y = cy - 4; y <= cy + 4; y++) {
      for (let x = cx - 4; x <= cx + 4; x++) {
        const d = Math.hypot(x - cx, y - cy);
        const g = realm.groundAt(x, y);
        if (g < T.SAND || g > T.UMBRAL && g !== T.PATH && g !== T.ICE && g !== T.INK) continue;
        if (d <= 1.5) realm.setGround(x, y, T.PATH);
        else if (d <= 3.6) realm.setGround(x, y, T.TIDAL);
      }
    }
    piece(game, realm, shrine, 0, 'pedestal', cx, cy, { solid: true });
  } else if (type === 'echo') {
    const n = tier <= 3 ? 5 : 6;
    for (let i = 0; i < n; i++) piece(game, realm, shrine, i, 'chime', ...at(i * 2 - (n - 1), (i % 2) + 1), { solid: true, lv: i });
    const len = 3 + Math.ceil((tier * 4) / 6);
    const seq = [];
    while (seq.length < len) { const v = rng.int(0, n - 1); if (v !== seq[seq.length - 1]) seq.push(v); }
    D.seq = seq;
  }
  index(game, realm, shrine);
  return shrine;
}

function toggleBraziers(D, i) {
  const c = i % D.cols, r = Math.floor(i / D.cols);
  for (const [dc, dr] of [[0, 0], [1, 0], [-1, 0], [0, 1], [0, -1]]) {
    const cc = c + dc, rr = r + dr;
    if (cc < 0 || rr < 0 || cc >= D.cols || rr >= D.rows) continue;
    const j = rr * D.cols + cc;
    D.lit[j] = D.lit[j] ? 0 : 1;
  }
}

// ---------------------------------------------------------------- runtime index

function index(game, realm, shrine) {
  const st = G(game);
  const pieces = shrine.data.pieces.map((id) => realm.entities.get(id)).filter(Boolean);
  st.shrines.set(shrine.id, { shrine, pieces });
}

const pieceOf = (game, shrine, i) => G(game).shrines.get(shrine.id)?.pieces.find((p) => p.data.i === i) ?? null;
const setPiece = (p, key, v) => { p.data[key] = v; p.set(key, v); };

// ---------------------------------------------------------------- solving

function ownsItem(game, player, id) {
  if ((game.call('countItem', player, id) || 0) > 0) return true;
  try { return JSON.stringify(player.gear ?? {}).includes('"' + id + '"'); } catch { return false; }
}

function solve(game, shrine, player) {
  const D = shrine.data;
  if (D.solved) return;
  D.solved = true;
  shrine.set('p', 255);
  const realm = game.realms.get(shrine.realm);
  const tier = D.tier ?? 1;
  const key = `shrine:${D.px},${D.py}`;
  game.world.flags[key] = true;
  game.sendWorld('unlocks', game.world.flags);
  for (const p of G(game).shrines.get(shrine.id)?.pieces ?? []) setPiece(p, 'on', 1);
  game.fx(realm, 'chest_open', shrine.x, shrine.y);
  game.fx(realm, 'quest_done', shrine.x, shrine.y);
  game.call('addGlint', 100 * tier * tier, 'shrine', player ?? null);
  if (player) {
    game.call('giveItem', player, 'tide_token', 2);
    const pool = game.content.modules.items?.SHRINE_TRINKETS ?? [];
    const missing = pool.filter((id) => !ownsItem(game, player, id));
    if (missing.length) game.call('giveItem', player, G(game).rng.pick(missing), 1);
    if (game.world.plots[plotIndex(D.px, D.py)]?.biome === 'greenmarrow' && !game.world.flags['relic:relic_01']) {
      game.world.flags['relic:relic_01'] = true;
      game.call('giveItem', player, 'relic_01', 1);
    }
  }
  game.toast(null, `${player?.name ?? 'Someone'} solved a ${game.content.biomes.byId[game.world.plots[plotIndex(D.px, D.py)]?.biome]?.name ?? ''} shrine!`, 'good');
  game.bus.emit('shrine.solved', { player: player ?? null, biome: game.world.plots[plotIndex(D.px, D.py)]?.biome, px: D.px, py: D.py, puzzle: D.puzzle });
}

function fail(game, shrine, x, y) {
  const D = shrine.data;
  D.prog = 0; D.show = 0; D.showT = -1.5; D.idle = 0;
  for (const p of G(game).shrines.get(shrine.id)?.pieces ?? []) if (p.data.it === 'plate' || p.data.it === 'chime') setPiece(p, 'on', 0);
  game.fx(shrine.realm, 'hit_clink', x, y);
}

// Plates and chimes share the input check: index `i` must equal the next element of the sequence.
function sequenceInput(game, shrine, i, player, x, y) {
  const D = shrine.data;
  if (D.solved) return;
  D.idle = 0;
  if (D.seq[D.prog] !== i) { fail(game, shrine, x, y); return; }
  D.prog += 1;
  D.show = D.seq.length;            // stop the demonstration while the player answers
  const p = pieceOf(game, shrine, i);
  if (p) setPiece(p, 'on', 1);
  game.fx(shrine.realm, D.puzzle === 'echo' ? 'shrine_chime' : 'pickup_flash', x, y, { n: i, ok: 1 });
  if (D.prog >= D.seq.length) solve(game, shrine, player);
}

function pressBrazier(game, shrine, i, player) {
  const D = shrine.data;
  if (D.solved) return;
  toggleBraziers(D, i);
  for (const p of G(game).shrines.get(shrine.id)?.pieces ?? []) setPiece(p, 'on', D.lit[p.data.i]);
  const p = pieceOf(game, shrine, i);
  if (p) game.fx(shrine.realm, D.lit[i] ? 'burn' : 'kiln_smoke', p.x, p.y);
  if (D.lit.every(Boolean)) solve(game, shrine, player);
}

function moveBlock(game, shrine, block, dx, dy) {
  const D = shrine.data;
  const realm = game.realms.get(shrine.realm);
  const tx = block.data.tx + dx, ty = block.data.ty + dy;
  const a = D.area, base = D.base;
  const ax = tx - base.x, ay = ty - base.y;
  if (ax < a.x0 || ax > a.x1 || ay < a.y0 || ay > a.y1) return false;
  if (!realm.isWalkable(tx, ty)) return false;
  for (const p of G(game).shrines.get(shrine.id)?.pieces ?? []) if (p !== block && p.data.it === 'block' && p.data.tx === tx && p.data.ty === ty) return false;
  for (const e of realm.query(tx + 0.5, ty + 0.5, 0.9)) if (e.type === 'player' || (e.type === 'structure' && e.data.solid)) return false;
  realm.setFlag(block.data.tx, block.data.ty, FLAG.SOLID, false);
  block.data.tx = tx; block.data.ty = ty;
  realm.move(block, tx + 0.5, ty + 0.5);
  realm.setFlag(tx, ty, FLAG.SOLID, true);
  game.fx(realm, 'footstep_dust', tx + 0.5, ty + 0.5);
  checkBlocks(game, shrine);
  return true;
}

function checkBlocks(game, shrine, player = null) {
  const D = shrine.data;
  const entry = G(game).shrines.get(shrine.id);
  if (!entry) return;
  const blocks = entry.pieces.filter((p) => p.data.it === 'block');
  let covered = 0;
  for (const m of entry.pieces.filter((p) => p.data.it === 'mark')) {
    const on = blocks.some((b) => b.data.tx === m.data.tx && b.data.ty === m.data.ty) ? 1 : 0;
    if (m.data.on !== on) setPiece(m, 'on', on);
    covered += on;
  }
  if (covered === 3 && !D.solved) solve(game, shrine, player ?? G(game).pushers.get(shrine.id) ?? null);
}

function resetBlocks(game, shrine) {
  const D = shrine.data;
  if (D.solved || D.puzzle !== 'blocks') return;
  const entry = G(game).shrines.get(shrine.id);
  const blocks = entry.pieces.filter((p) => p.data.it === 'block').sort((a, b) => a.data.i - b.data.i);
  const realm = game.realms.get(shrine.realm);
  const base = D.base;
  blocks.forEach((b, k) => {
    const [dx, dy] = D.start[k];
    realm.setFlag(b.data.tx, b.data.ty, FLAG.SOLID, false);
    b.data.tx = base.x + dx; b.data.ty = base.y + dy;
    realm.move(b, b.data.tx + 0.5, b.data.ty + 0.5);
  });
  for (const b of blocks) realm.setFlag(b.data.tx, b.data.ty, FLAG.SOLID, true);
  checkBlocks(game, shrine);
  game.fx(realm, 'summon_puff', shrine.x, shrine.y + 1);
}

// Direction a push goes: dominant axis from the player toward the block.
function pushDir(fromX, fromY, toX, toY) {
  const dx = toX - fromX, dy = toY - fromY;
  return Math.abs(dx) >= Math.abs(dy) ? [Math.sign(dx) || 1, 0] : [0, Math.sign(dy) || 1];
}

// ---------------------------------------------------------------- interactions

function usePiece(game, player, p) {
  const st = G(game);
  const shrine = game.realms.get(p.realm)?.entities.get(p.data.shrine);
  if (!shrine) return { ok: false, err: 'invalid' };
  const D = shrine.data;
  switch (p.data.it) {
    case 'chime': sequenceInput(game, shrine, p.data.i, player, p.x, p.y); return { ok: true };
    case 'plate': return { ok: false, err: 'invalid' };         // plates are stepped on
    case 'brazier': if (D.solved) return { ok: true }; pressBrazier(game, shrine, p.data.i, player); return { ok: true };
    case 'block': {
      if (D.solved) return { ok: true };
      const [dx, dy] = pushDir(player.entity.x, player.entity.y, p.x, p.y);
      st.pushers.set(shrine.id, player);
      return moveBlock(game, shrine, p, dx, dy) ? (checkBlocks(game, shrine, player), { ok: true }) : { ok: false, err: 'busy' };
    }
    case 'pedestal': {
      if (!D.solved) { solve(game, shrine, player); return { ok: true }; }
      // the solved pedestal carries you back to the altar
      const x = shrine.x, y = shrine.data.ty + shrine.data.h + 0.6;
      game.fx(p.realm, 'waystone_warp', player.entity.x, player.entity.y);
      game.movePlayer(player, p.realm, x, y);
      game.fx(p.realm, 'waystone_warp', x, y);
      return { ok: true };
    }
    default: return { ok: false, err: 'invalid' };
  }
}

function useAltar(game, player, shrine) {
  const D = shrine.data;
  if (D.solved) { game.toast(player, 'This shrine is quiet now. Its gift was given.', 'info'); return { ok: true }; }
  if (D.puzzle === 'blocks') { resetBlocks(game, shrine); game.toast(player, 'The blocks slide back to where they began.', 'info'); return { ok: true }; }
  const hints = {
    plates: 'Watch the plates light up, then step on them in that order.',
    braziers: 'Light every brazier. Each one you touch flips its neighbours.',
    tidelock: 'The pedestal waits beyond the flats. Cross at low tide.',
    echo: 'Listen to the chimes, then strike them in the same order.',
  };
  D.show = 0; D.showT = 0; D.prog = 0;
  game.toast(player, hints[D.puzzle] ?? 'Solve the shrine.', 'info');
  return { ok: true };
}

function digSpot(game, player, spot) {
  const st = G(game);
  const last = st.dig.get(player.id) ?? -1;
  if (game.now - last < 0.3) return { ok: false, err: 'cooldown' };
  st.dig.set(player.id, game.now);
  const D = spot.data;
  D.hits = (D.hits ?? 0) + 1;
  const need = D.need ?? 10;
  spot.set('p', Math.min(255, Math.round((D.hits / need) * 255)));
  const realm = game.realms.get(spot.realm);
  game.fx(realm, 'hit_stone', spot.x, spot.y);
  if (D.hits < need) return { ok: true };
  for (const { item, qty } of D.loot ?? []) game.call('dropItem', realm, spot.x, spot.y, item, qty, { owner: player.id });
  game.fx(realm, 'chest_open', spot.x, spot.y);
  const relic = (D.loot ?? []).find((l) => String(l.item).startsWith('relic_') && l.item !== 'relic_fragment');
  if (relic) game.toast(null, `${player.name} unearthed ${game.content.items.byId[relic.item]?.name ?? relic.item}!`, 'good');
  game.bus.emit('dig.done', { player, spot, loot: D.loot ?? [] });
  realm.remove(spot);
  return { ok: true };
}

// ---------------------------------------------------------------- per-tick logic

function nearPlayers(game, shrine, r) {
  const out = [];
  for (const p of game.players.values()) {
    const e = p.entity;
    if (e && e.realm === shrine.realm && Math.abs(e.x - shrine.x) < r && Math.abs(e.y - shrine.y) < r + 3) out.push(p);
  }
  return out;
}

function showSequence(game, shrine, dt) {
  const D = shrine.data;
  if (D.prog > 0) {                                   // player is answering: idle timeout restarts the demonstration
    D.idle += dt;
    if (D.idle > IDLE_RESET) fail(game, shrine, shrine.x, shrine.y + 2);
    return;
  }
  D.showT += dt;
  const entry = G(game).shrines.get(shrine.id);
  if (!entry) return;
  if (D.show < D.seq.length) {
    const i = D.seq[D.show];
    const p = entry.pieces.find((q) => q.data.i === i && (q.data.it === 'plate' || q.data.it === 'chime'));
    if (D.showT >= 0 && p && p.data.on !== 2 && D.showT < SHOW_ON) {
      setPiece(p, 'on', 2);
      if (D.puzzle === 'echo') game.fx(shrine.realm, 'shrine_chime', p.x, p.y, { n: i });
    }
    if (D.showT >= SHOW_ON && p?.data.on === 2) setPiece(p, 'on', 0);
    if (D.showT >= SHOW_STEP) { D.showT = 0; D.show += 1; }
  } else if (D.showT >= SHOW_PAUSE) { D.show = 0; D.showT = 0; }
}

function platesTick(game, shrine, players) {
  const entry = G(game).shrines.get(shrine.id);
  for (const pl of players) {
    const e = pl.entity;
    const tx = Math.floor(e.x), ty = Math.floor(e.y);
    const plate = entry.pieces.find((p) => p.data.it === 'plate' && p.data.tx === tx && p.data.ty === ty);
    const was = pl.shrinePlate ?? 0;
    pl.shrinePlate = plate ? plate.id : 0;
    if (plate && plate.id !== was && !(plate.data.on === 1 && shrine.data.prog > 0)) sequenceInput(game, shrine, plate.data.i, pl, plate.x, plate.y);
  }
}

function blocksTick(game, shrine, players, dt) {
  const st = G(game);
  const entry = st.shrines.get(shrine.id);
  for (const pl of players) {
    const e = pl.entity, inp = pl.lastInput;
    if (!inp || Math.abs(inp.mx) + Math.abs(inp.my) < 0.5) { pl.pushT = 0; continue; }
    const [dx, dy] = Math.abs(inp.mx) >= Math.abs(inp.my) ? [Math.sign(inp.mx), 0] : [0, Math.sign(inp.my)];
    const fx = Math.floor(e.x + dx * 0.6), fy = Math.floor(e.y + dy * 0.6);
    const block = entry.pieces.find((p) => p.data.it === 'block' && p.data.tx === fx && p.data.ty === fy);
    if (!block) { pl.pushT = 0; continue; }
    pl.pushT = (pl.pushT ?? 0) + dt;
    if (pl.pushT < 0.3) continue;
    pl.pushT = 0;
    st.pushers.set(shrine.id, pl);
    if (moveBlock(game, shrine, block, dx, dy)) checkBlocks(game, shrine, pl);
  }
}

// ---------------------------------------------------------------- system

export default {
  name: 'shrines',

  init(game) {
    GAMES.set(game, { shrines: new Map(), dig: new Map(), pushers: new Map(), acc: 0, rng: game.rng.fork('shrines') });
    game.services.register('buildShrine', (realm, plot, lx, ly, type) => buildShrine(game, realm, plot, lx, ly, type));
    game.services.register('shrineType', (px, py) => shrineType(game, game.world.plots[plotIndex(px, py)]));
    game.call('registerInteract', 'shrine_piece', (g, player, e) => usePiece(g, player, e));
    game.call('registerInteract', 'shrine', (g, player, e) => useAltar(g, player, e));
    game.call('registerInteract', 'dig_spot', (g, player, e) => digSpot(g, player, e));
  },

  load(game) {
    const st = G(game);
    st.shrines.clear();
    const realm = game.realms.get('overworld');
    if (!realm) return;
    for (const e of realm.entities.values()) {
      if (e.type !== 'structure') continue;
      if (e.kind === 'shrine_piece') {
        for (const k of ['it', 'on', 'lv']) if (e.data[k] != null) e.set(k, e.data[k]);
        e.radius = 0.5;
      } else if (e.kind === 'shrine') {
        e.set('it', e.data.puzzle);
        e.set('p', e.data.solved ? 255 : 0);
      } else if (e.kind === 'dig_spot') {
        e.set('p', Math.min(255, Math.round(((e.data.hits ?? 0) / (e.data.need ?? 10)) * 255)));
      }
    }
    for (const e of realm.entities.values()) if (e.type === 'structure' && e.kind === 'shrine') index(game, realm, e);
  },

  handlers: {
    'shrine.act': (game, player, d) => {
      if (!d || !isInt(d.id, 1, 2 ** 31) || !isInt(d.i, 0, 64)) return { ok: false, err: 'invalid' };
      const realm = game.realms.get(player.entity.realm);
      const shrine = realm?.entities.get(d.id);
      if (!shrine || shrine.kind !== 'shrine') return { ok: false, err: 'invalid' };
      const p = pieceOf(game, shrine, d.i);
      if (!p) return { ok: false, err: 'invalid' };
      if (Math.hypot(p.x - player.entity.x, p.y - player.entity.y) > 3.5) return { ok: false, err: 'range' };
      return usePiece(game, player, p);
    },
  },

  tick(game, dt) {
    const st = G(game);
    if (!st.shrines.size || game.players.size === 0) return;
    st.acc += dt;
    if (st.acc < 0.1) return;
    const step = st.acc;
    st.acc = 0;
    for (const { shrine } of st.shrines.values()) {
      if (shrine.removed || shrine.data.solved) continue;
      const players = nearPlayers(game, shrine, 9);
      if (!players.length) continue;
      const P = shrine.data.puzzle;
      if (P === 'plates' || P === 'echo') showSequence(game, shrine, step);
      if (P === 'plates') platesTick(game, shrine, players);
      if (P === 'blocks') blocksTick(game, shrine, players, step);
    }
  },
};

export { toggleBraziers, moveBlock, resetBlocks, checkBlocks, pieceOf };

// WP14: the pacing bot charges puzzle time and solves shrines through the same path as players.
export { solve as solveShrine };
